import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.z3u3TMv0.js";const m=JSON.parse('{"title":"MiniTavern で画像を設定","description":"設定 → 画像生成 → 画像接続：本機 A1111／ComfyUI またはクラウド画像 API。","frontmatter":{"title":"MiniTavern で画像を設定","description":"設定 → 画像生成 → 画像接続：本機 A1111／ComfyUI またはクラウド画像 API。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"MiniTavern で画像を設定 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"設定 → 画像生成 → 画像接続：本機 A1111／ComfyUI またはクラウド画像 API。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/local/image-gen/connect-app"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/local/image-gen/connect-app"}]]},"headers":[],"relativePath":"ja/local/image-gen/connect-app.md","filePath":"ja/local/image-gen/connect-app.md","lastUpdated":1787224147000}'),o={name:"ja/local/image-gen/connect-app.md"};function n(i,t,l,c,s,h){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="minitavern-で画像を設定" tabindex="-1">MiniTavern で画像を設定 <a class="header-anchor" href="#minitavern-で画像を設定" aria-label="Permalink to &quot;MiniTavern で画像を設定&quot;">​</a></h1><p>本文は App 経路：<strong>設定 → 画像生成 → 画像接続</strong>。</p><p>画像パラメータ、返信画像、キーワードトリガーは <a href="/ultra_guides/ja/manual/model-link#画像生成接続--返信画像--キーワード">モデル接続 · 画像生成</a>。</p><h2 id="画像接続の新規作成" tabindex="-1">画像接続の新規作成 <a class="header-anchor" href="#画像接続の新規作成" aria-label="Permalink to &quot;画像接続の新規作成&quot;">​</a></h2><ol><li>MiniTavern → 下部 <strong>設定</strong>。</li><li><strong>画像生成</strong> → <strong>画像接続</strong>。</li><li><strong>新規</strong>。</li><li><strong>プラットフォーム</strong>を選び、Base URL／API Key／モデルを記入（プラットフォームにより異なる）。</li><li><strong>測連</strong>成功後に保存し、デフォルトへ（一覧が対応する場合）。</li></ol><h2 id="本機-a1111" tabindex="-1">本機 A1111 <a class="header-anchor" href="#本機-a1111" aria-label="Permalink to &quot;本機 A1111&quot;">​</a></h2><p>先に <a href="./a1111">A1111 インストールと <code>--api --listen</code></a> を完了。</p><table tabindex="0"><thead><tr><th>項目</th><th>記入例</th></tr></thead><tbody><tr><td>プラットフォーム</td><td><strong>A1111(SD WebUI)</strong>（またはカスタム A1111 プロトコル）</td></tr><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:7860</code></td></tr><tr><td>API Key</td><td>通常空欄可；WebUI で <code>--api-auth</code> 時は案内に従う</td></tr><tr><td>モデル</td><td>空欄可、または WebUI の checkpoint 名（App 一覧準拠）</td></tr></tbody></table><p><code>YOUR_PC_IP</code> を PC の LAN IP に。<br><strong><code>http://127.0.0.1:7860</code> は不可</strong>（それは PC 自身でありスマホではない）。</p><h2 id="本機-comfyui" tabindex="-1">本機 ComfyUI <a class="header-anchor" href="#本機-comfyui" aria-label="Permalink to &quot;本機 ComfyUI&quot;">​</a></h2><p>先に <a href="./comfyui">ComfyUI インストールと <code>--listen</code></a> を完了。</p><table tabindex="0"><thead><tr><th>項目</th><th>記入例</th></tr></thead><tbody><tr><td>プラットフォーム</td><td><strong>ComfyUI</strong>（またはカスタム ComfyUI プロトコル）</td></tr><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:8188</code>（Desktop はよく <code>:8000</code>）</td></tr><tr><td>API Key</td><td>通常空欄可</td></tr><tr><td>モデル／checkpoint</td><td>App が取得した一覧準拠；マシン上に対応ファイルが必要</td></tr></tbody></table><p>測連失敗時：スマホブラウザで同じ Base URL を先に開き、ファイアウォールや未 listen でないか確認。</p><h2 id="クラウド画像-任意" tabindex="-1">クラウド画像（任意） <a class="header-anchor" href="#クラウド画像-任意" aria-label="Permalink to &quot;クラウド画像（任意）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>プラットフォーム</th><th>いつ使うか</th></tr></thead><tbody><tr><td>ChatGPT(OpenAI)</td><td>公式 Images API（通常有料）</td></tr><tr><td>Gemini(Google)</td><td>Gemini 画像モデル（多くは有料帯、Google 価格準拠）</td></tr><tr><td>OpenRouter</td><td>画像対応上流へルーティング</td></tr><tr><td>Qwen</td><td>通義万相／Qwen-Image（百煉に無料枠があるか確認）</td></tr><tr><td>カスタム (OpenAI Images)</td><td>硅基流動、Agnes など <code>/images/generations</code> 互換ゲートウェイ（図生図も generations、<code>/images/edits</code> ではない）</td></tr></tbody></table><p>無料クラウドと Key 取得は <a href="/ultra_guides/ja/free-cloud/#無料の画像生成">無料クラウド · 画像生成</a>。</p><h2 id="チャットでの生図" tabindex="-1">チャットでの生図 <a class="header-anchor" href="#チャットでの生図" aria-label="Permalink to &quot;チャットでの生図&quot;">​</a></h2><p>デフォルト画像接続を設定後（主チャットモデルも必要——プロンプト分析／転写用）：</p><table tabindex="0"><thead><tr><th>入口</th><th>説明</th></tr></thead><tbody><tr><td><code>/imagine プロンプト</code> を入力</td><td>自由生図。主モデルが先に判定：チャット関連（例「自撮りを一枚」→ 対話＋キャラ参考図）か、無関連（例「子犬の写真」）。同時に入力欄へ添付可：主モデルがそれらの図を見てからプロンプトを書き、生図時も参考；添付の有無にかかわらずキャラ図／ユーザー図の要否は別判定。添付は生図吹き出しの小プレビューに出る。枚数は <strong>画像設定 → 生成枚数</strong>。失敗時は吹き出しが残り再試行可</td></tr><tr><td><code>/imagine scene</code> または添付 → 物語に基づく</td><td>直近対話から今の一幕、固定 1 枚</td></tr><tr><td><code>/imagine last</code> または添付 → 最後のメッセージに基づく</td><td>最後のメッセージから、固定 1 枚</td></tr><tr><td><code>/imagine background</code> または添付 → 背景図を生成</td><td>環境背景、固定 1 枚</td></tr><tr><td>長押し吹き出し → 生図</td><td>その吹き出しから、固定 1 枚</td></tr><tr><td>返信画像（スマート／キーワード）</td><td>先に画像設定で「返信画像」をオンしトリガー方式を選ぶ。通常メッセージ（添付可）の後、現在の対話からバイパス生図、固定 1 枚；添付はスタイル参考</td></tr></tbody></table><p>画像接続未設定時、添付生図四モードまたは <code>/imagine</code> 送信は「設定へ／キャンセル」を出し、Toast せず入力欄も消さない。チャットのスマート／キーワード自動出図で接続がなければ Toast。画像設定で「返信画像」オン時に接続がなければダイアログ、スイッチはオフのまま。</p><p>画像のみ設定しチャットモデル未設定だと、転写が必要な入口は失敗する。</p><h2 id="排錯クイック" tabindex="-1">排錯クイック <a class="header-anchor" href="#排錯クイック" aria-label="Permalink to &quot;排錯クイック&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現象</th><th>切り分け</th></tr></thead><tbody><tr><td>測連失敗／タイムアウト</td><td>PC サービス稼働中か；<code>--api</code>／<code>--listen</code>；IP とポート；同一 Wi‑Fi</td></tr><tr><td>本機ブラウザ可、スマホ不可</td><td>ファイアウォール；ゲスト隔離；<code>127.0.0.1</code> を記入していないか</td></tr><tr><td>A1111 404</td><td><code>--api</code> なし；Base URL に余分なパス</td></tr><tr><td>Comfy が回り続ける</td><td>PC 側 Comfy のキューとエラー；显存不足；利用可能な checkpoint なし</td></tr><tr><td>参考図があるが顔が合わない（Comfy）</td><td>現行デフォルト workflow は参考図非消費 → A1111 またはクラウドへ</td></tr><tr><td><code>/imagine</code> 失敗で吹き出しが消える</td><td>失敗時は元吹き出しが残り再試行表示；停止すると未完了のプレースホルダは消える</td></tr></tbody></table><p>より完全なチャットエラーコードは <a href="/ultra_guides/ja/manual/errors">エラー排錯</a>。</p>',24)])])}const g=e(o,[["render",n]]);export{m as __pageData,g as default};
